// Fallback logic for tests without full translations — returns Russian by default
export function getTestTranslation(testId: string, lang: Lang): TestTranslation | null {
  const t = testTranslations[testId];
  if (!t) return null;
  return t[lang] ?? t["ru"] ?? null;
}

